  wobblyBranch(len * 0.72, depth - 1, baseWidth);
  left(spread);
  back(len);
}

function centerKnot(radius, turns, col, wobble) {
  home();
  penDown();
  penColor(col);
  penWidth(3.2);
  for (var i = 0; i < turns; i++) {
    left(137 + (Math.random() - 0.5) * wobble);
    forward(radius + i * 0.3);
    left(90);
    forward(radius * 0.5);
    right(70);
    forward(radius * 0.3);
    left(110);
  }
}

function cornerSpiral(cx, cy, startHead, col1, col2) {
  goTo(cx, cy);
  penDown();
  for (var i = 0; i < 22; i++) {
    penColor(i % 2 === 0 ? col1 : col2);
    penWidth(1.5 + i * 0.2);
    setHeading(startHead + i * 137);
    left((Math.random() - 0.5) * 22);
    forward(8 + i * 2.4);
  }
}

