function petal(len, depth, lean) {
  if (depth === 0) return;
  var colors = ['hotpink','violet','deepskyblue','limegreen','gold','darkorange','orchid','coral'];
  penColor(colors[depth % colors.length]);
  penWidth(depth);
  for (var i = 0; i < 8; i++) {
    forward(len / 8);
    left(lean * 0.18 + Math.floor(Math.random() * 5) - 1);
  }
  var savedLean = lean;
  right(12 + lean * 0.3 + Math.floor(Math.random() * 5));
  petal(len * 0.6, depth - 1, lean + 5);
  for (var j = 0; j < 8; j++) {
    back(len / 8);
  }
  left(24 + lean * 0.3 + Math.floor(Math.random() * 5));
  petal(len * 0.6, depth - 1, savedLean + 5);
  for (var k = 0; k < 8; k++) {
    back(len / 8);
  }
  right(12 + lean * 0.3);
}

